Saves a workbook, opens the saved file with the Workbook file-name constructor and prints the text of a cell read back from it.

Example:
#include "aspose/cells_foss/Style.h"
#include "aspose/cells_foss/Color.h"
#include "aspose/cells_foss/Font.h"
// Authored example: save a workbook, open the saved file again and read a cell back.
#include <iostream>
#include "aspose/cells_foss/Workbook.h"
#include "aspose/cells_foss/WorksheetCollection.h"
#include "aspose/cells_foss/Worksheet.h"
#include "aspose/cells_foss/Cells.h"
#include "aspose/cells_foss/Cell.h"

using namespace Aspose::Cells_FOSS;

int main() {
    {
        Workbook workbook;
        workbook.GetWorksheets()[0].GetCells()["A1"].PutValue("Hello workbook");
        workbook.Save("authored_roundtrip.xlsx");
    }
    Workbook loaded("authored_roundtrip.xlsx");
    Worksheet& sheet = loaded.GetWorksheets()[0];
    std::cout << sheet.GetCells()["A1"].GetStringValue() << std::endl;
    return 0;
}
