FQN: Example: Bold Header and Number Format on Cells
Kind: verified_example
Provenance: authored
Verification: passed
Authored example: written for foss-mcp against the pinned library, not taken from the upstream README; published only after the ingestion verifier compiled or ran it against that commit.
Harness: #include lines from other blocks on this page added by the verifier: #include "aspose/cells_foss/Color.h"
Reads a cell's style, switches its font to bold, applies a two-decimal number format to another cell and saves the workbook.

Example:
#include "aspose/cells_foss/Color.h"
// Authored example: give a header cell a bold font and a number format, then save.
#include "aspose/cells_foss/Workbook.h"
#include "aspose/cells_foss/WorksheetCollection.h"
#include "aspose/cells_foss/Worksheet.h"
#include "aspose/cells_foss/Cells.h"
#include "aspose/cells_foss/Cell.h"
#include "aspose/cells_foss/Style.h"
#include "aspose/cells_foss/Font.h"

using namespace Aspose::Cells_FOSS;

int main() {
    Workbook workbook;
    Worksheet& sheet = workbook.GetWorksheets()[0];
    Cell title = sheet.GetCells()["A1"];
    title.PutValue("Total");
    Style titleStyle = title.GetStyle();
    Font font = titleStyle.GetFont();
    font.SetBold(true);
    titleStyle.SetFont(font);
    title.SetStyle(titleStyle);

    Cell amount = sheet.GetCells()["A2"];
    amount.PutValue(1234.5);
    Style amountStyle = amount.GetStyle();
    amountStyle.SetNumberFormat("0.00");
    amount.SetStyle(amountStyle);

    workbook.Save("authored_styles.xlsx");
    return 0;
}
