Harness: #include lines from other blocks on this page added by the verifier: #include "aspose/cells_foss/Style.h" | #include "aspose/cells_foss/Color.h" | #include "aspose/cells_foss/Font.h"
Creates a new workbook, writes a small table of text and numeric values into the first worksheet and saves it as an .xlsx file in the current directory.

Example:
#include "aspose/cells_foss/Style.h"
#include "aspose/cells_foss/Color.h"
#include "aspose/cells_foss/Font.h"
// Authored example: write text and numbers into the first worksheet and save an .xlsx file.
#include "aspose/cells_foss/Workbook.h"
#include "aspose/cells_foss/WorksheetCollection.h"
#include "aspose/cells_foss/Worksheet.h"
#include "aspose/cells_foss/Cells.h"
#include "aspose/cells_foss/Cell.h"

using namespace Aspose::Cells_FOSS;

int main() {
    Workbook workbook;
    Worksheet& sheet = workbook.GetWorksheets()[0];
    Cells& cells = sheet.GetCells();
    cells["A1"].PutValue("Item");
    cells["B1"].PutValue("Quantity");
    cells["A2"].PutValue("Pencil");
    cells["B2"].PutValue(12);
    cells["A3"].PutValue("Notebook");
    cells["B3"].PutValue(4.5);
    workbook.Save("authored_values.xlsx");
    return 0;
}
